/**
 * Interactive Java visualizer — deterministic step engine.
 *
 * Deliberately NOT a Java interpreter: each supported example is a curated,
 * hand-verified program whose execution trace is generated by a dedicated
 * pure function. Unsupported syntax is impossible by construction.
 */

export type VizKind = "variables" | "array" | "loop" | "bubble" | "selection" | "string";

export interface VizVar { name: string; value: string; type: string }
export interface VizArrayCell { index: number; value: number; state: "idle" | "compare" | "swap" | "sorted" | "min" }

export interface VizStep {
  line: number;               // source line being executed (1-based)
  code: string;               // that line's text
  explanation: string;
  vars: VizVar[];
  cells?: VizArrayCell[];     // for array-based examples
  output?: string;            // accumulated program output so far
  done?: boolean;
}

export interface VizExample {
  id: string;
  kind: VizKind;
  title: string;
  description: string;
  source: string[];
  steps: VizStep[];
}

const v = (name: string, value: string, type = "int"): VizVar => ({ name, value, type });

// ---------- generators ----------

function variablesExample(): VizExample {
  const source = [
    "int age = 15;",
    "int year = 2026;",
    "year = year + 1;",
    "System.out.println(age + year);",
  ];
  const steps: VizStep[] = [
    { line: 1, code: source[0], explanation: "Declares variable 'age' and stores 15 in memory.", vars: [v("age", "15")], output: "" },
    { line: 2, code: source[1], explanation: "Declares 'year' with value 2026.", vars: [v("age", "15"), v("year", "2026")], output: "" },
    { line: 3, code: source[2], explanation: "Reassigns 'year': 2026 + 1 = 2027. The old value is replaced.", vars: [v("age", "15"), v("year", "2027")], output: "" },
    { line: 4, code: source[3], explanation: "Prints age + year → 15 + 2027 = 2042.", vars: [v("age", "15"), v("year", "2027")], output: "2042", done: true },
  ];
  return { id: "variables", kind: "variables", title: "Variables & Memory", description: "Watch values move in and out of memory.", source, steps };
}

function arrayExample(): VizExample {
  const source = [
    "int[] scores = {90, 55, 78};",
    "scores[1] = 88;",
    "int best = scores[0];",
    "for (int i = 1; i < 3; i++) {",
    "    if (scores[i] > best) best = scores[i];",
    "}",
    "System.out.println(best);",
  ];
  const cells = (vals: number[], hi: number[] = [], sorted: number[] = [], min: number[] = []): VizArrayCell[] =>
    vals.map((value, index) => ({
      index, value,
      state: sorted.includes(index) ? "sorted" : hi.includes(index) ? "compare" : min.includes(index) ? "min" : "idle",
    }));
  const steps: VizStep[] = [
    { line: 1, code: source[0], explanation: "Creates an array of 3 ints at indices 0, 1, 2.", vars: [v("scores", "[90, 55, 78]", "int[]")], cells: cells([90, 55, 78]), output: "" },
    { line: 2, code: source[1], explanation: "Writes 88 into index 1, replacing 55.", vars: [v("scores", "[90, 88, 78]", "int[]")], cells: cells([90, 88, 78], [1]), output: "" },
    { line: 3, code: source[2], explanation: "Copies scores[0] into 'best' — a snapshot, not a link.", vars: [v("scores", "[90, 88, 78]", "int[]"), v("best", "90")], cells: cells([90, 88, 78], [0]), output: "" },
    { line: 4, code: source[3], explanation: "Loop starts: i = 1. Condition 1 < 3 is true.", vars: [v("scores", "[90, 88, 78]", "int[]"), v("best", "90"), v("i", "1")], cells: cells([90, 88, 78]), output: "" },
    { line: 5, code: source[4], explanation: "scores[1]=88 is NOT > best=90, so best stays 90.", vars: [v("scores", "[90, 88, 78]", "int[]"), v("best", "90"), v("i", "1")], cells: cells([90, 88, 78], [1, 0]), output: "" },
    { line: 4, code: source[3], explanation: "i becomes 2. Condition 2 < 3 still true.", vars: [v("scores", "[90, 88, 78]", "int[]"), v("best", "90"), v("i", "2")], cells: cells([90, 88, 78]), output: "" },
    { line: 5, code: source[4], explanation: "scores[2]=78 is NOT > 90 either.", vars: [v("scores", "[90, 88, 78]", "int[]"), v("best", "90"), v("i", "2")], cells: cells([90, 88, 78], [2, 0]), output: "" },
    { line: 4, code: source[3], explanation: "i becomes 3. Condition 3 < 3 is false — loop ends.", vars: [v("scores", "[90, 88, 78]", "int[]"), v("best", "90"), v("i", "3")], cells: cells([90, 88, 78]), output: "" },
    { line: 6, code: source[5], explanation: "Prints the maximum: 90.", vars: [v("scores", "[90, 88, 78]", "int[]"), v("best", "90")], cells: cells([90, 88, 78], [], [0]), output: "90", done: true },
  ];
  return { id: "array", kind: "array", title: "Arrays & Loops", description: "Track indices, values and loop conditions together.", source, steps };
}

function loopExample(): VizExample {
  const source = [
    "int sum = 0;",
    "for (int i = 1; i <= 4; i++) {",
    "    sum = sum + i;",
    "}",
    "System.out.println(sum);",
  ];
  const steps: VizStep[] = [];
  let sum = 0;
  steps.push({ line: 1, code: source[0], explanation: "Accumulator 'sum' starts at 0.", vars: [v("sum", "0"), v("i", "—")], output: "" });
  for (let i = 1; i <= 4; i++) {
    steps.push({ line: 2, code: source[1], explanation: `Init/update: i = ${i}. Check ${i} <= 4 → true.`, vars: [v("sum", String(sum)), v("i", String(i))], output: "" });
    sum += i;
    steps.push({ line: 3, code: source[2], explanation: `sum = ${sum - i} + ${i} = ${sum}.`, vars: [v("sum", String(sum)), v("i", String(i))], output: "" });
  }
  steps.push({ line: 2, code: source[1], explanation: "i becomes 5. Check 5 <= 4 → false. Loop ends.", vars: [v("sum", String(sum)), v("i", "5")], output: "" });
  steps.push({ line: 5, code: source[4], explanation: `Prints the total: ${sum}.`, vars: [v("sum", String(sum))], output: String(sum), done: true });
  return { id: "loop", kind: "loop", title: "For Loop Anatomy", description: "See init, condition, body and update as separate beats.", source, steps };
}

function sortExample(kind: "bubble" | "selection"): VizExample {
  const isBubble = kind === "bubble";
  const title = isBubble ? "Bubble Sort" : "Selection Sort";
  const arr = [5, 2, 8, 1];
  const source = isBubble
    ? ["for (int i = 0; i < n - 1; i++) {", "  for (int j = 0; j < n - 1 - i; j++) {", "    if (a[j] > a[j+1]) swap;", "  }", "}"]
    : ["for (int i = 0; i < n - 1; i++) {", "  int min = i;", "  for (int j = i + 1; j < n; j++)", "    if (a[j] < a[min]) min = j;", "  swap(a[i], a[min]);", "}"];

  // Generate real trace by simulating the algorithm.
  const a = [...arr];
  const steps: VizStep[] = [];
  const cell = (vals: number[], cmp: number[] = [], sorted: number[] = [], min: number[] = []): VizArrayCell[] =>
    vals.map((value, index) => ({
      index, value,
      state: sorted.includes(index) ? "sorted" : cmp.includes(index) ? "compare" : min.includes(index) ? "min" : "idle",
    }));

  if (isBubble) {
    for (let i = 0; i < a.length - 1; i++) {
      for (let j = 0; j < a.length - 1 - i; j++) {
        steps.push({
          line: 3, code: "if (a[j] > a[j+1]) swap;",
          explanation: `Compare a[${j}]=${a[j]} with a[${j + 1}]=${a[j + 1]}.`,
          vars: [v("i", String(i)), v("j", String(j))],
          cells: cell(a, [j, j + 1]), output: "",
        });
        if (a[j] > a[j + 1]) {
          [a[j], a[j + 1]] = [a[j + 1], a[j]];
          steps.push({
            line: 3, code: "swap(a[j], a[j+1]);",
            explanation: `${a[j + 1]} < ${a[j]} → swap. Array becomes [${a.join(", ")}].`,
            vars: [v("i", String(i)), v("j", String(j))],
            cells: cell(a, [j, j + 1], [], []), output: "",
          });
        }
      }
      steps.push({
        line: 1, code: source[0],
        explanation: `Pass ${i + 1} complete — largest remaining value bubbled to index ${a.length - 1 - i}.`,
        vars: [v("i", String(i))],
        cells: cell(a, [], Array.from({ length: a.length - i }, (_, k) => a.length - 1 - k)), output: "",
      });
    }
  } else {
    for (let i = 0; i < a.length - 1; i++) {
      let min = i;
      for (let j = i + 1; j < a.length; j++) {
        steps.push({
          line: 4, code: "if (a[j] < a[min]) min = j;",
          explanation: `Compare a[${j}]=${a[j]} with current min a[${min}]=${a[min]}.`,
          vars: [v("i", String(i)), v("min", String(min))],
          cells: cell(a, [], [], [min, j]), output: "",
        });
        if (a[j] < a[min]) min = j;
      }
      if (min !== i) [a[i], a[min]] = [a[min], a[i]];
      steps.push({
        line: 6, code: "swap(a[i], a[min]);",
        explanation: `Smallest remaining value ${a[i]} placed at index ${i}. Sorted so far: indices 0–${i}.`,
        vars: [v("i", String(i)), v("min", String(min))],
        cells: cell(a, [], Array.from({ length: i + 1 }, (_, k) => k)), output: "",
      });
    }
  }

  steps.push({
    line: source.length, code: "// done",
    explanation: `Array sorted: [${a.join(", ")}].`,
    vars: [v("a", `[${a.join(", ")}]`, "int[]")],
    cells: cell(a, [], a.map((_, i) => i)),
    output: a.join(" "), done: true,
  });

  return {
    id: kind, kind, title, description: "Step through the comparisons and swaps.",
    source, steps,
  };
}

function stringExample(): VizExample {
  const source = [
    "String word = \"java\";",
    "for (int i = 0; i < word.length(); i++) {",
    "    char c = word.charAt(i);",
    "    System.out.print(c);",
    "}",
  ];
  const chars = "java".split("");
  const steps: VizStep[] = [
    { line: 1, code: source[0], explanation: "String 'word' holds 4 characters at indices 0–3.", vars: [v("word", "\"java\"", "String"), v("i", "—")], cells: chars.map((ch, index) => ({ index, value: ch.charCodeAt(0), state: "idle" as const })), output: "" },
  ];
  let out = "";
  for (let i = 0; i < chars.length; i++) {
    out += chars[i];
    steps.push({
      line: 3, code: source[2],
      explanation: `i = ${i}: charAt(${i}) → '${chars[i]}'. Strings are immutable — charAt only reads.`,
      vars: [v("word", "\"java\"", "String"), v("i", String(i)), v("c", `'${chars[i]}'`, "char")],
      cells: chars.map((ch, index) => ({ index, value: ch.charCodeAt(0), state: index === i ? "compare" as const : "idle" as const })),
      output: out,
    });
  }
  steps.push({ line: 5, code: source[4], explanation: "Loop ends (i=4 fails i < 4). Output so far is the word itself.", vars: [v("word", "\"java\"", "String")], cells: chars.map((ch, index) => ({ index, value: ch.charCodeAt(0), state: "sorted" as const })), output: out, done: true });
  return { id: "string", kind: "string", title: "String Traversal", description: "See charAt() walk a string index by index.", source, steps };
}

function methodExample(): VizExample {
  const source = [
    "static int square(int x) {",
    "    return x * x;",
    "}",
    "int a = 4;",
    "int b = square(a);",
    "System.out.println(b);",
  ];
  const steps: VizStep[] = [
    { line: 4, code: source[3], explanation: "Variable 'a' is declared with value 4 in main's frame.", vars: [v("main.a", "4"), v("square.x", "—")], output: "" },
    { line: 5, code: source[4], explanation: "main calls square(4): a NEW frame is pushed; parameter x receives a COPY of a's value (pass-by-value).", vars: [v("main.a", "4"), v("square.x", "4")], output: "" },
    { line: 2, code: source[1], explanation: "Inside square: return x * x → 4 × 4 = 16.", vars: [v("main.a", "4"), v("square.x", "4"), v("return", "16")], output: "" },
    { line: 5, code: source[4], explanation: "square's frame is popped; its return value 16 is assigned to b in main. square.x is gone — frames don't leak.", vars: [v("main.a", "4"), v("main.b", "16"), v("square.x", "—")], output: "" },
    { line: 6, code: source[5], explanation: "Prints b → 16. Java passes primitives by value: square cannot modify main.a.", vars: [v("main.a", "4"), v("main.b", "16")], output: "16", done: true },
  ];
  return { id: "method", kind: "variables", title: "Method Calls & Stack", description: "Watch frames push and pop — pass-by-value made visible.", source, steps };
}

export const VIZ_EXAMPLES: VizExample[] = [
  variablesExample(),
  arrayExample(),
  loopExample(),
  sortExample("bubble"),
  sortExample("selection"),
  stringExample(),
  methodExample(),
];

export function getVizExample(id: string): VizExample | undefined {
  return VIZ_EXAMPLES.find((e) => e.id === id);
}

/** Playback helpers — pure, testable. */
export function clampStep(i: number, steps: VizStep[]): number {
  return Math.max(0, Math.min(i, steps.length - 1));
}
